def main():
    output = ROOT / 'eyes' / 'shell' / 'constellation-art'
    output.mkdir(parents=True, exist_ok=True)
    for file, (name, description, outline, details) in ART.items():
        groups = []
        for width, paths in ((2.1, outline), (1.2, details)):
            body = '\n'.join(f'    <path d="{escape(" ".join(p.split()), quote=True)}"/>' for p in paths.split('|') if p.strip())
            groups.append(f'  <g fill="none" stroke="#ffffff" stroke-width="{width}" stroke-linecap="round" stroke-linejoin="round">\n{body}\n  </g>')
        svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512" data-origin="spacelibre-original">\n  <title>{escape(name)}</title>\n  <desc>{escape(description)} Original AI-assisted vector illustration.</desc>\n' + '\n'.join(groups) + '\n</svg>\n'
        (output / file).write_text(svg, encoding='utf-8', newline='\n')
    print(f'Wrote {len(ART)} original constellation illustrations.')

if __name__ == '__main__':
    main()
